Section RWA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x5 x6 x7 x10 x12 x18 x19 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m0 : amem) (HW nbS scale : Z) (ws : list Z) (jk : list byte).
  Variable Q : machine_state -> Prop.
  Hypothesis HNS : 1 <= nbS <= 256.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : Forall (fun w => 0 <= w < 256) ws.
  Hypothesis HSC : 1 <= scale <= 11.
  Hypothesis LJK : zlen jk = 256 - nbS.
  Hypothesis HHW : ablk HW (HW + 256).
  Hypothesis ZHW : zshadow m0 HW 256.
  Hypothesis AWH : appW [(HW, HW + 256)].
  Hypothesis RHW : rng RNG HW 256.
  Hypothesis RHWs : rng RNG (shad HW) (nshad (256 + HW mod 8)).

  Notation ARRK m1 k := (u8arr asegs m1 HW (map (Z_to_bv 8) (map (RSC.rsw1 scale) (firstn (Z.to_nat k) ws) ++ skipn (Z.to_nat k) ws)
                                             ++ jk)).
  Notation ST pc mm x11 x14 x15 x16 x17 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 (Z_to_bv 64 scale) x14 x15 x16 x17
             x18 x19 (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma rwA_loop : forall f k m1 (x16 x17 : word),
    Z.of_nat f = nbS - k -> 0 <= k < nbS -> ARRK m1 k ->
    munch [(HW, HW + 256)] m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 ->
    (forall m2 (y11 y14 y15 y16 y17 : word), ARRK m2 nbS -> munch [(HW, HW + 256)] m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 ->
       evtF asegs RNG Q (ST 0x804fc m2 y11 y14 y15 y16 y17)) ->
