Section SHA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x6 x7 x12 x14 x18 x19 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word).
  Variables (m0 : amem) (WK scale : Z).
  Variable Q : machine_state -> Prop.
  Notation NS4 := (Z_to_bv 64 (18446744073709551616 - 4 * scale)).
  Hypothesis HSC : 1 <= scale <= 11.
  Hypothesis HWK : ablk WK (WK + 52).
  Hypothesis ZRK : zshadow m0 WK 52.
  Hypothesis AWR : appW [(WK, WK + 52)].
  Hypothesis RRK : rng RNG WK 52.
  Hypothesis RRKs : rng RNG (shad WK) (nshad (52 + WK mod 8)).
  Notation ST pc mm x5 x10 x11 x16 x17 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 (Z_to_bv 64 scale) x14 NS4 x16
             x17 x18 x19 (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma shA_loop : forall f s rank m1 r (x5 x17 : word),
    shift_rank f s scale rank = Ok r -> Z.of_nat f = s - scale -> scale < s <= 12 -> zlen rank = 13 ->
    Forall (fun v => 0 <= v <= 256) rank ->
    u32arr asegs m1 WK (map (Z_to_bv 64) rank) ->
    munch [(WK, WK + 52)] m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 ->
    (forall m2 (y5 y10 y11 y16 y17 : word), u32arr asegs m2 WK (map (Z_to_bv 64) r) -> zlen r = 13 ->
       Forall (fun v => 0 <= v <= 256) r ->
       munch [(WK, WK + 52)] m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 ->
       evtF asegs RNG Q (ST 0x8058c m2 y5 y10 y11 y16 y17)) ->
    evtF asegs RNG Q (ST 0x80528 m1 x5 (Z_to_bv 64 (WK + 4 * s)) (Z_to_bv 64 (WK + 4 * s)) (Z_to_bv 64 s) x17).
